#!/usr/bin/env node
// tier: T2
/**
 * awareness-snapshot-inject.mjs — SessionStart injector
 *
 * OBSIDIAN-PRISM-OS-MS0/U-AWARENESS-INJECT.
 *
 * Reads state/shared/AWARENESS-SNAPSHOT.md (generated by
 * scripts/awareness-snapshot.mjs — companion to /awareness-snapshot
 * skill) and emits a compact ~10-line digest as SessionStart
 * additionalContext so every fresh chat knows "what's built / what's
 * not used / what's drifted" without running anything.
 *
 * If the snapshot file is missing or stale (>24h old), regenerates it
 * inline before reading. The script runs in ~1.6s so SessionStart cost
 * is bounded.
 *
 * Disable: PRISM_AWARENESS_INJECT=0
 * Force-regen always: PRISM_AWARENESS_INJECT_FORCE_REGEN=1
 * Stale threshold:    PRISM_AWARENESS_INJECT_STALE_HOURS=<n>  (default 24)
 */

import { readFileSync, statSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";

const ENABLED = process.env.PRISM_AWARENESS_INJECT !== "0";
const FORCE_REGEN = process.env.PRISM_AWARENESS_INJECT_FORCE_REGEN === "1";
const STALE_HOURS = parseInt(process.env.PRISM_AWARENESS_INJECT_STALE_HOURS, 10) || 24;
const SNAPSHOT_PATH = "H:/prism/state/shared/AWARENESS-SNAPSHOT.md";
const SNAPSHOT_SCRIPT = "H:/prism/scripts/awareness-snapshot.mjs";
const STALE_MS = STALE_HOURS * 3600 * 1000;
const REGEN_TIMEOUT_MS = 8_000;

function regenSnapshot() {
  try {
    spawnSync(process.execPath, [SNAPSHOT_SCRIPT], {
      stdio: "ignore",
      timeout: REGEN_TIMEOUT_MS,
    });
  } catch { /* non-fatal */ }
}

function isStale() {
  if (!existsSync(SNAPSHOT_PATH)) return true;
  try {
    const ageMs = Date.now() - statSync(SNAPSHOT_PATH).mtimeMs;
    return ageMs > STALE_MS;
  } catch { return true; }
}

function readSnapshot() {
  try { return readFileSync(SNAPSHOT_PATH, "utf8"); }
  catch { return null; }
}

/**
 * Extract a compact digest from the full snapshot markdown. We keep:
 *   - the headline bullet block (5 lines)
 *   - the utilization totals (one table)
 *   - the top 3 orphans (the action item list)
 *   - the top 3 drift cases
 * Everything else is dropped to stay <15 lines.
 */
function compact(md) {
  if (!md) return null;
  const lines = md.split(/\r?\n/);
  const out = [];

  // Locate sections by heading text.
  const findSection = (heading) => {
    const i = lines.findIndex((l) => l.trim().startsWith(`## ${heading}`));
    if (i < 0) return [];
    const result = [];
    for (let j = i + 1; j < lines.length; j++) {
      const t = lines[j].trim();
      if (t.startsWith("## ")) break;
      result.push(lines[j]);
    }
    return result;
  };

  const headline = findSection("Headline").filter((l) => l.trim().startsWith("-"));
  const totalsBlock = findSection("Graph utilization (filtered to semantic layers L0..L8 + L10)");
  const orphans = findSection("Top orphans (built + documented + unwired — fix candidates)")
    .filter((l) => l.trim().startsWith("-"));
  const drift = findSection("Milestone drift (envelope vs git reality)")
    .filter((l) => l.trim().startsWith("-"));

  // Find the totals table rows (lines starting with `|`).
  const totalsRows = totalsBlock.filter((l) => l.trim().startsWith("| **"));

  out.push("## 🧭 PRISM Awareness (auto-injected — see /awareness-snapshot for full)");
  out.push("");
  if (headline.length > 0) {
    out.push("**Built:**");
    headline.slice(0, 4).forEach((l) => out.push(l));
    out.push("");
  }
  if (totalsRows.length > 0) {
    // Reduce table to a single compact line.
    const counts = {};
    for (const row of totalsRows) {
      const m = row.match(/\| \*\*(\w+)\*\* \| (\d+) \|/);
      if (m) counts[m[1]] = m[2];
    }
    out.push(
      `**Utilization** (5K scanned): ${counts.hub ?? "?"} hubs · ` +
      `${counts.sink ?? "?"} sinks · ${counts.source ?? "?"} sources · ` +
      `${counts.orphan ?? "?"} orphans · ${counts.ghost ?? "?"} ghosts · ` +
      `${counts.normal ?? "?"} normal`,
    );
    out.push("");
  }
  if (orphans.length > 0) {
    out.push("**Top orphans** (built+documented+unwired — punch list):");
    orphans.slice(0, 3).forEach((l) => out.push(l));
    out.push("");
  }
  if (drift.length > 0) {
    out.push("**Envelope drift:**");
    drift.slice(0, 3).forEach((l) => out.push(l));
    out.push("");
  }
  out.push(
    "_Full report: `state/shared/AWARENESS-SNAPSHOT.md`. " +
    "Drill: `/master-index <query>` · `/utilization-dashboard` · `/awareness-snapshot` regen._",
  );
  return out.join("\n");
}

function emit(systemReminder) {
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "SessionStart",
      additionalContext: systemReminder,
    },
  }));
}

function main() {
  if (!ENABLED) { process.exit(0); }
  if (FORCE_REGEN || isStale()) { regenSnapshot(); }
  const md = readSnapshot();
  if (!md) { process.exit(0); }
  const block = compact(md);
  if (!block) { process.exit(0); }
  emit(block);
  process.exit(0);
}

try { main(); }
catch (err) {
  process.stderr.write(`[awareness-snapshot-inject] ${err?.message || err}\n`);
  process.exit(0);
}
